// Confini della giornata su Europe/Rome
const now = new Date();
const p = Object.fromEntries(new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Rome', year:'numeric', month:'2-digit', day:'2-digit',
  hour:'2-digit', minute:'2-digit', second:'2-digit', hour12:false
}).formatToParts(now).map(x => [x.type, x.value]));
const wallNow = Date.UTC(+p.year, +p.month-1, +p.day, +p.hour, +p.minute, +p.second);
const offset  = wallNow - now.getTime();
const startMs = Date.UTC(+p.year, +p.month-1, +p.day, 0, 0, 0) - offset;
return [{ json: {
  giorno:     p.year + '-' + p.month + '-' + p.day,
  today_unix: Math.floor(startMs/1000),
  day_start:  new Date(startMs).toISOString(),
  day_end:    now.toISOString()
} }];

// Trasferimenti e lead dall'esito REALE del tool, non da un giudizio dell'LLM.
// La risposta del flusso "Richiesta operatore" e nei tool_results della conversazione.
const rip = $('Chiamate di oggi').first().json.riepilogo || {};
const sd  = $getWorkflowStaticData('global');
sd.esiti = sd.esiti || {};

function dettagli(){ try { return $('Dettaglio conversazione').all().map(x => x.json); } catch(e){ return []; } }

function esitoDi(det){
  let out = null;
  for (const t of (det && det.transcript) || []){
    for (const r of t.tool_results || []){
      if (r.tool_name !== 'async_transfer_to_human') continue;
      let v = r.result_value;
      if (typeof v === 'string' && v.indexOf('Background task completed:') === 0){
        try { v = JSON.parse(v.replace(/^Background task completed:\s*/,'')).tool_result.result_value; }
        catch(e){ continue; }
      }
      let p = v;
      if (typeof p === 'string'){ try { p = JSON.parse(p); } catch(e){ p = { message: String(v) }; } }
      if (!p || typeof p !== 'object') continue;
      if (p.status === 'in_progress') continue;                 // solo presa in carico
      const msg = String(p.message || '');
      if (/gi[aà] in corso/i.test(msg)) continue;               // richiesta duplicata
      if (p.result === 'SUCCESS') return 'TRASFERITO';          // se aggiungi result allo schema del tool
      if (p.result === 'FAIL'){ out = 'LEAD'; continue; }
      if (/specialista libero|passo subito/i.test(msg)) return 'TRASFERITO';
      if (/occupati/i.test(msg)) out = 'LEAD';
    }
  }
  return out;
}

// esiti freschi dai dettagli scaricati in questo giro
for (const det of dettagli()){
  const id = det && det.conversation_id;
  if (!id) continue;
  const e = esitoDi(det);
  const chiusa = det.status !== 'in-progress' && det.status !== 'in_progress';
  if (chiusa) sd.esiti[id] = e || 'NESSUNO';   // anche NESSUNO, per non riscaricarla ogni 3 minuti
  det.__esito = e;
}
const freschi = {};
for (const det of dettagli()){ if (det && det.conversation_id) freschi[det.conversation_id] = det.__esito; }

const candidati = Array.isArray(rip.candidati) ? rip.candidati : [];
let transfers = 0, leads = 0, richieste = 0;
const durTrasf = [], durRich = [];
for (const c of candidati){
  const e = (c.id in freschi) ? freschi[c.id] : (sd.esiti[c.id] === 'NESSUNO' ? null : sd.esiti[c.id]);
  if (e === 'TRASFERITO'){ transfers++; richieste++; if (c.dur>0){ durTrasf.push(c.dur); durRich.push(c.dur); } }
  else if (e === 'LEAD'){ leads++; richieste++; if (c.dur>0) durRich.push(c.dur); }
}
// senza risposta dalla lista non inventiamo zeri
const nd = rip.ha_risposto === false;
const media = a => a.length ? a.reduce((s,x)=>s+x,0)/a.length/60 : null;
const r1 = v => v==null ? null : Math.round(v*10)/10;

return [{ json:{
  live_calls:              rip.live_calls ?? null,
  live_durations:          rip.live_durations || [],
  avg_min_all:             r1(rip.avg_sec_all==null ? null : rip.avg_sec_all/60),
  avg_min_transferred:     r1(media(durTrasf)),
  total_calls_today:       rip.total_calls ?? null,
  short_calls_today:       rip.short_calls ?? null,
  transfers_today:         nd ? null : transfers,
  leads_today:             nd ? null : leads,
  handoff_requested_today: nd ? null : richieste,
  avg_min_handoff:         r1(media(durRich)),
  updated_at:              new Date().toISOString()
} }];

// Perimetro della giornata: la lista ElevenLabs (ancorata all'inizio chiamata)
// e l'unica fonte. Nessun criterio LLM, nessuna dipendenza da Directus.
function pagine(n){ try { return $(n).all().map(x => x.json); } catch(e){ return []; } }
const pg = pagine('ElevenLabs');
const grezze = pg.flatMap(p => Array.isArray(p.conversations) ? p.conversations : []);
const perId = new Map();
for (const c of grezze){ const k = c.conversation_id || c.id; if (k) perId.set(k, c); }
const haRisposto = pg.some(p => p && Array.isArray(p.conversations));
const conv = haRisposto ? [...perId.values()] : null;

const nowSec  = Math.floor(Date.now()/1000);
const durata  = c => Number(c.call_duration_secs ?? c.duration_secs ?? 0) || 0;
const inCorso = c => c.status === 'in-progress' || c.status === 'in_progress';

const inProg = conv ? conv.filter(inCorso) : [];
const chiuse = conv ? conv.filter(c => !inCorso(c) && durata(c) > 0) : [];

// chiamate che hanno invocato il tool di trasferimento: dalla lista, senza scaricare i dettagli
const TOOL = 'async_transfer_to_human';
const candidati = (conv || [])
  .filter(c => Array.isArray(c.tool_names) && c.tool_names.indexOf(TOOL) !== -1)
  .map(c => ({ id: c.conversation_id || c.id, dur: durata(c), aperta: inCorso(c) }));

// cache: l'esito di una chiamata chiusa non cambia piu, quindi il dettaglio si scarica una volta sola
const sd = $getWorkflowStaticData('global');
const giorno = $('Prep giorno').first().json.giorno;
if (sd.giorno !== giorno){ sd.giorno = giorno; sd.esiti = {}; }
sd.esiti = sd.esiti || {};

const daLeggere = candidati.filter(c => c.aperta || !sd.esiti[c.id]).map(c => c.id);

const riepilogo = {
  ha_risposto:    haRisposto,
  total_calls:    conv ? conv.length : null,
  short_calls:    conv ? conv.filter(c => !inCorso(c) && durata(c) < 15).length : null,
  live_calls:     conv ? inProg.length : null,
  live_durations: inProg.map(function(c){
    var st = Number(c.start_time_unix_secs);
    if(!isFinite(st) || st <= 0) return 0;
    if(st > 1e12) st = Math.floor(st/1000);
    return Math.max(0, nowSec - st);
  }),
  avg_sec_all:    chiuse.length ? chiuse.reduce((s,c)=>s+durata(c),0)/chiuse.length : null,
  candidati
};

if (!daLeggere.length) return [{ json: { riepilogo, nulla_da_leggere: true } }];
return daLeggere.map(id => ({ json: { riepilogo, conversation_id: id } }));
